import { requireRole } from "@/lib/authz";
import { connectDatabase } from "@/lib/db";
import { Product } from "@/models/Product";
import { VendorProfile } from "@/models/VendorProfile";
import { VendorProductForm } from "@/components/storefront";
export const metadata={title:"Seller dashboard"};
export default async function VendorDashboardPage(){const user=await requireRole(["vendor"]);await connectDatabase();const [profileResult,products]=await Promise.all([VendorProfile.findOne({userId:user.id}).lean(),Product.find({vendorId:user.id,deletedAt:null}).sort({createdAt:-1}).limit(100).lean()]);const profile=Array.isArray(profileResult)?profileResult[0]:profileResult;return <section className="container py-12"><span className="eyebrow">Seller workspace</span><h1 className="mt-3 text-4xl font-black">{profile?.storeName||"Your store"}</h1><p className="mt-2 text-[#777487]">Manage your catalogue and track listing reviews.</p><div className="mt-7 grid gap-4 sm:grid-cols-3">{[["Total listings",products.length],["Live products",products.filter(p=>p.status==="active").length],["In review",products.filter(p=>p.status==="pending-review").length]].map(([label,value])=><div key={label} className="rounded-3xl border border-[#f0e9e1] bg-white p-6"><p className="text-sm text-[#777487]">{label}</p><p className="mt-2 text-3xl font-black">{value}</p></div>)}</div><div className="mt-9"><VendorProductForm/></div><h2 className="mt-10 text-2xl font-black">Your listings</h2><div className="mt-4 space-y-3">{products.map(p=><article key={String(p._id)} className="flex flex-wrap justify-between gap-3 rounded-2xl border border-[#f0e9e1] bg-white p-5"><div><h3 className="font-black">{p.title}</h3><p className="mt-1 text-sm text-[#777487]">৳{p.price.toLocaleString("en-BD")} · {p.stock} in stock</p></div><span className="h-fit rounded-full bg-[#fff0e3] px-3 py-1 text-xs font-bold capitalize">{p.status.replace("-"," ")}</span></article>)}{!products.length&&<p className="rounded-2xl border border-dashed border-[#e8ddd2] p-8 text-sm text-[#777487]">Your store is ready for its first listing.</p>}</div></section>;}